using System.Runtime.InteropServices;

namespace Simulator.Core.Kos;

public enum KosPortDirection
{
    Input,
    Output,
}

/// <summary>One port of a kos_simulation model DLL, as reported by descrByIndex.</summary>
public sealed record KosPort(
    int Index, string Name, KosPortDirection Direction, int Width, bool IsParameter, ushort VarType)
{
    /// <summary>VARTYPE VT_R8: the only element type the generated models use.</summary>
    public const ushort VtR8 = 5;

    public bool IsDouble => VarType == VtR8;
}

/// <summary>
/// Host for a model DLL generated by the kos_simulation Simulink target
/// (dll_malloc.tlc) — the same ABI as AK13Dynamics.dll and DynamicsGorEl.dll:
/// mdlCreate/mdlStart/mdlStep/mdlDestroy, getTimeStepSize/getCurrentTime and
/// port discovery through descrCounter/descrByIndex. Ports are read and written
/// in place through the addresses the model reports.
/// </summary>
/// <remarks>
/// The DLL must match the process bitness (the current models are x86, so the
/// host has to run as a 32-bit process). The generated runtime keeps at most 10
/// live instances per loaded DLL. Not thread-safe.
/// </remarks>
public sealed unsafe class KosModel : IDisposable
{
    [StructLayout(LayoutKind.Sequential)]
    private struct Description
    {
        public IntPtr Name;
        public int IsParameter;
        public int IsFromBus;
        public ushort Type;
        public int Width;
        public IntPtr Address;
    }

    private readonly IntPtr _library;
    private IntPtr _model;
    private bool _started;

    private readonly delegate* unmanaged[Cdecl]<IntPtr, void> _start;
    private readonly delegate* unmanaged[Cdecl]<IntPtr, void> _step;
    private readonly delegate* unmanaged[Cdecl]<IntPtr, void> _destroy;
    private readonly delegate* unmanaged[Cdecl]<IntPtr, double> _timeStep;
    private readonly delegate* unmanaged[Cdecl]<IntPtr, double> _currentTime;

    private readonly Dictionary<string, (KosPort Port, IntPtr Address)> _ports;

    private KosModel(string path, IntPtr library)
    {
        Path = path;
        _library = library;
        var create = (delegate* unmanaged[Cdecl]<IntPtr>)Export("mdlCreate");
        _start = (delegate* unmanaged[Cdecl]<IntPtr, void>)Export("mdlStart");
        _step = (delegate* unmanaged[Cdecl]<IntPtr, void>)Export("mdlStep");
        _destroy = (delegate* unmanaged[Cdecl]<IntPtr, void>)Export("mdlDestroy");
        _timeStep = (delegate* unmanaged[Cdecl]<IntPtr, double>)Export("getTimeStepSize");
        _currentTime = (delegate* unmanaged[Cdecl]<IntPtr, double>)Export("getCurrentTime");
        var counter = (delegate* unmanaged[Cdecl]<int>)Export("descrCounter");
        var describe = (delegate* unmanaged[Cdecl]<IntPtr, int, Description>)Export("descrByIndex");

        _model = create();
        if (_model == IntPtr.Zero)
        {
            throw new SimulationException(
                $"{System.IO.Path.GetFileName(path)}: mdlCreate failed (model init error, or more than 10 live instances).");
        }

        var count = counter();
        var ports = new List<KosPort>(count);
        _ports = new Dictionary<string, (KosPort, IntPtr)>(count, StringComparer.Ordinal);
        for (var i = 0; i < count; i++)
        {
            var d = describe(_model, i);
            if (d.Name == IntPtr.Zero || d.Address == IntPtr.Zero) continue;
            var name = Marshal.PtrToStringAnsi(d.Name)!;
            var port = new KosPort(i, name,
                d.IsFromBus != 0 ? KosPortDirection.Input : KosPortDirection.Output,
                d.Width, d.IsParameter != 0, d.Type);
            ports.Add(port);
            _ports[name] = (port, d.Address);
        }
        Ports = ports;
        Inputs = ports.Where(p => p.Direction == KosPortDirection.Input).ToList();
        Outputs = ports.Where(p => p.Direction == KosPortDirection.Output).ToList();
    }

    public string Path { get; }
    public IReadOnlyList<KosPort> Ports { get; }
    public IReadOnlyList<KosPort> Inputs { get; }
    public IReadOnlyList<KosPort> Outputs { get; }

    /// <summary>Base step of the generated model, s (SimCore frame, e.g. 0.025).</summary>
    public double StepSize => _timeStep(Handle);

    public double Time => _currentTime(Handle);

    public static KosModel Load(string path)
    {
        var full = System.IO.Path.GetFullPath(path);
        if (!File.Exists(full)) throw new FileNotFoundException("Model DLL not found.", full);
        CheckBitness(full);
        return new KosModel(full, NativeLibrary.Load(full));
    }

    public bool HasPort(string name) => _ports.ContainsKey(name);

    public KosPort Port(string name) => Lookup(name).Port;

    /// <summary>Scalar port value (element 0 for vector ports).</summary>
    public double this[string name]
    {
        get => Read(name)[0];
        set => Write(name, [value]);
    }

    public double[] Read(string name)
    {
        var (port, address) = Lookup(name, requireDouble: true);
        var values = new double[port.Width];
        new ReadOnlySpan<double>((void*)address, port.Width).CopyTo(values);
        return values;
    }

    public void Write(string name, ReadOnlySpan<double> values)
    {
        var (port, address) = Lookup(name, requireDouble: true);
        if (port.Direction != KosPortDirection.Input)
            throw new InvalidOperationException($"Port '{name}' is an output.");
        if (values.Length != port.Width)
            throw new ArgumentException($"Port '{name}' has width {port.Width}, got {values.Length} values.");
        values.CopyTo(new Span<double>((void*)address, port.Width));
    }

    /// <summary>Calls mdlStart. Set initial inputs before; Step() starts automatically.</summary>
    public void Start()
    {
        if (_started) return;
        _start(Handle);
        _started = true;
    }

    /// <summary>Advances the model by one base step (<see cref="StepSize"/>).</summary>
    public void Step()
    {
        Start();
        _step(Handle);
    }

    public void Dispose()
    {
        if (_model != IntPtr.Zero)
        {
            _destroy(_model);
            _model = IntPtr.Zero;
            NativeLibrary.Free(_library);
        }
    }

    private IntPtr Handle =>
        _model != IntPtr.Zero ? _model : throw new ObjectDisposedException(nameof(KosModel));

    private (KosPort Port, IntPtr Address) Lookup(string name, bool requireDouble = false)
    {
        _ = Handle;
        if (!_ports.TryGetValue(name, out var entry))
            throw new KeyNotFoundException($"Model has no port '{name}'.");
        if (requireDouble && !entry.Port.IsDouble)
            throw new NotSupportedException($"Port '{name}' has VARTYPE {entry.Port.VarType}; only VT_R8 is supported.");
        return entry;
    }

    private IntPtr Export(string name) =>
        NativeLibrary.TryGetExport(_library, name, out var p)
            ? p
            : throw new SimulationException($"{System.IO.Path.GetFileName(Path)} does not export '{name}' — not a kos_simulation model DLL?");

    // A 32-bit DLL cannot be loaded into a 64-bit process (and vice versa);
    // report that plainly instead of a bare BadImageFormatException.
    private static void CheckBitness(string path)
    {
        var dllArch = PeMachine(path);
        if (dllArch is null) return;  // not a PE file (Linux/macOS shared library)
        var process = RuntimeInformation.ProcessArchitecture;
        if (dllArch != process)
        {
            throw new SimulationException(
                $"{System.IO.Path.GetFileName(path)} is {dllArch}, but this process is {process}. " +
                (dllArch == Architecture.X86
                    ? "Run the host as 32-bit, e.g. dotnet publish -r win-x86 --self-contained."
                    : "Rebuild the DLL for the process architecture."));
        }
    }

    internal static Architecture? PeMachine(string path)
    {
        using var f = File.OpenRead(path);
        using var r = new BinaryReader(f);
        if (f.Length < 0x40 || r.ReadUInt16() != 0x5A4D) return null;  // "MZ"
        f.Position = 0x3C;
        var pe = r.ReadInt32();
        if (pe <= 0 || pe + 6 > f.Length) return null;
        f.Position = pe;
        if (r.ReadUInt32() != 0x00004550) return null;  // "PE\0\0"
        return r.ReadUInt16() switch
        {
            0x014C => Architecture.X86,
            0x8664 => Architecture.X64,
            0xAA64 => Architecture.Arm64,
            _ => null,
        };
    }
}
